import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"35、【晉】 坤下離上","description":"周易集註 - 35、【晉】 坤下離上","frontmatter":{"title":"35、【晉】 坤下離上","description":"周易集註 - 35、【晉】 坤下離上"},"headers":[],"relativePath":"classics/jizhu/039.md","filePath":"classics/jizhu/039.md"}'),l={name:"classics/jizhu/039.md"};function t(h,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_35、【晉】-坤下離上" tabindex="-1">35、【晉】 坤下離上 <a class="header-anchor" href="#_35、【晉】-坤下離上" aria-label="Permalink to “35、【晉】 坤下離上”">​</a></h1><p>晉者進也，以日出地上，前進而明也。不言進而言晉者，進止有前進之義，無明之義。晉則有進而光明之義，所以不言進也。《序卦》：“物不可以終壯，故受之以晉。”蓋物既盛壯，則必前進，所以次大壯。</p><p>康侯，安國之侯也。錫者，賜與也。蕃庶，見其恩之者隆。三接，見其禮之者頻。坤錯幹，馬之象。中爻艮綜震，震為蕃，蕃之象。庶者眾也，坤為眾，庶之象。蕃庶者，言所錫之馬眾多也。晝日，離之象。離居三，三之象。艮為手，相接之象。日者君也，坤者臣也。坤為邑國，日在地上，照臨其邑國之侯，有寵有錫馬三接之象。易止有是象，無是事，如棟撓、金車、玉鉉之類皆是也。諸儒不知象，乃以周官校人大行人實之，失象旨矣。</p><p>《彖》曰：晉，進也。明出地上，順而麗乎大明，柔進而上行，是以康侯用錫馬蕃庶，晝日三接也。</p><p>釋卦名，又以卦象卦德卦綜釋卦辭。明出地上者，離日出於地之上也。順而麗乎大明者，坤順而附麗乎大明也。柔進而上行者，晉綜明夷，因二卦同體，文王綜為一卦，故《雜卦》曰“晉晝也，明夷誅也”，言明夷下卦之離，進而為晉上卦之離也。若以人事論，明出地上，乃世道維新，治教休明之時也。順以臣言，大明以君言。順者小心承順也，麗者猶言攀龍鱗、附鳳翼也。柔進而上行，則成虛中矣，是虛中下賢之君，而居於五之位也。上句以時言，中句以臣之德言，下句以君言，言為康侯者，必際是時，備是德，遇是君，方得是寵也。</p><h3 id="《象》曰-明出地上-晉-君子以自昭明德。" tabindex="-1">《象》曰：明出地上，晉，君子以自昭明德。 <a class="header-anchor" href="#《象》曰-明出地上-晉-君子以自昭明德。" aria-label="Permalink to “《象》曰：明出地上，晉，君子以自昭明德。”">​</a></h3><p>地乃陰土，譬之人慾之私。自者，我所本有也。日本明，入於地則暗矣，猶人之德本明，但溺於人慾之私則暗矣。故自昭其明德，亦猶日之出地也。自昭者，格物致知，以去其蔽明之私;誠意正心修身，以踐其自昭之實也。明德者，即行道而有得於我者。天下無道外之德，即五倫體之於身也。此德塞乎天地，橫乎四海，如杲日當空，人人得而見之，故曰明，非《大學》舊注虛靈不昧之謂也。至健莫如天，故君子以之自彊。至明莫如日，故君子以之自昭，所以二象皆以自字言之。</p><p>初六，晉如摧如，貞吉，罔孚，裕無咎。摧音崔</p><p>晉如者，升進也。摧者，崔嵬之崔。高也，中爻艮山在坤土之上，崔之象也。四近君，又陽爻，故有崔如之象。若以為摧如，則與小象獨行正，不相合矣。依鄭為南山崔崔之崔是也。貞者盡其在我，不畔援茍且，汲汲然求進也。吉者，終得遂其進也。罔孚者，二三不信之也。中爻坎，為狐疑，不信之象也。當升進之時，眾人通欲進，初卑下，故二三不見信。觀《小象》曰“獨行正”，六三曰“眾允”，可知矣。裕者不以進退為欣戚，從容以處之，而我之自修者，猶夫初也。無咎者，不失其身也。貞，即下文罔孚裕無咎。</p><p>初六以陰居下，當升進之時，而應近君之四，故有晉如崔如之象，佔者守正則吉矣。設或不我見信，不可急於求信，惟寬裕以處之，則可以無咎矣。若求信之心切，則不免枉道失身，安得無咎哉。此所以利貞則吉也。</p><h3 id="《象》曰-晉如摧如-獨行正也。裕無咎-未受命也。" tabindex="-1">《象》曰：晉如摧如，獨行正也。裕無咎，未受命也。 <a class="header-anchor" href="#《象》曰-晉如摧如-獨行正也。裕無咎-未受命也。" aria-label="Permalink to “《象》曰：晉如摧如，獨行正也。裕無咎，未受命也。”">​</a></h3><p>獨行者，獨進也。中爻艮綜震，足行之象也。正者，應與之正道也，言升進之時，四陽在上，近乎其君，赫赫崔嵬。初又卑下，眾人不進，而初獨進之，似不可進矣。然四與初為正應，進之亦正道也，未害其為進也。未受命者，離日在上，未受命君王之命也。未受命，則無官守，所以得綽綽有餘裕。應四未應五，故曰未受命。六二曰，受茲介福於王母，二受字相同。中爻艮為手，有授受之象，故文王卦辭曰接。初二爻皆言受，皆有手象。</p><p>六二，晉如愁如，貞吉，受茲介福於其王母。</p><p>中爻坎為加憂，為心病，愁之象也。其所以愁者，四乃大臣中鼫鼠之小人也，近君而據下三爻升進之路，二欲升進無應援。五陰柔，二愁五之不斷。四邪辟，二愁四之見害，此其所以愁也。貞者中正之德也。初六之貞，未有貞而勉之也。六二之貞，因其本有而教以守之也。吉者中正之德，久而必彰，上之人自當求之，下文所言受介福於王母是也。介者大也，受介福者，應六五大明之君，因其同德而任用之，加之以寵祿也。王母者六五也。離為日，王之象也。離為中女，母之象也。</p><p>六二中正，上無應援，故有欲進而愁之象。佔者如是而能守正，則吉而受福矣。</p><h3 id="《象》曰-受茲介福-以中正也。" tabindex="-1">《象》曰：受茲介福，以中正也。 <a class="header-anchor" href="#《象》曰-受茲介福-以中正也。" aria-label="Permalink to “《象》曰：受茲介福，以中正也。”">​</a></h3><p>以中正者，以六二有此中正之德也。八卦正位，坤在二，所以受介福，詳見雜說。</p><p>六三，眾允，悔亡。</p><p>坤為眾，眾之象也。允者信也。初罔孚，未允也。二愁如，猶恐未允也。三則允矣。悔亡者，亡其不中正之悔也。</p><p>六三不中正，當欲進之時，宜眾所不信，而有悔矣。然所居之地，近乎離明，又順體之極，有順上嚮明之志，則所謂不中正者，皆因親近大明而中正矣，是以眾皆信之。同下二陰上進，故有眾允之象。而佔者則悔亡也。</p><h3 id="《象》曰-眾允之志-上行也。" tabindex="-1">《象》曰：眾允之志，上行也。 <a class="header-anchor" href="#《象》曰-眾允之志-上行也。" aria-label="Permalink to “《象》曰：眾允之志，上行也。”">​</a></h3><p>上者大明也，上行者，上順麗於大明也。上從大明之君，眾志之所同也。</p><p>九四，晉如鼫鼠，貞厲*。鼫音石，市亦切</p><p>鼫鼠，《廣韻》以為螻蛄，則非鼠矣。《玉篇》以為形大如鼠，頭似兔，尾有毛青黃色，則又鼠之異者也。蔡邕以為五技鼠，能飛不能過屋，能緣不能窮木，能遊不能度谷，能穴不能掩身，能走無能先人，則飛鼠也。郭景純以為形大如鼠，號在田中食粟豆，則田鼠也。《廣韻》鼫字與碩字同一類，二字從石，皆音石。《詩》“碩鼠刺貪”，碩大也。陽大陰小，此爻陽，故為大鼠，即《詩》之碩鼠無疑矣。中爻艮，變爻亦艮，鼠之象也。鼠竊人之物，然晝則伏藏，夜則走動，蓋不敢見日而畏人者也。離為日，晉者晝也，鼠豈能見之哉。但當進之時，見眾人俱進，彼亦同進，不復畏其晝矣。貞者當進之時，九四晉如，非不正也。</p><p>九四不中不正，當晉之時，竊近君之位，居三陰之上，上而畏五六大明之知，下而畏三陰群小之忌，故有鼫鼠日下，惟恐人見之象。佔者如是，雖正亦危矣。</p><ul><li>原文作“貞吉”，為“貞厲”之誤。</li></ul><h3 id="《象》曰-鼫鼠貞厲-位不當也。" tabindex="-1">《象》曰：鼫鼠貞厲，位不當也。 <a class="header-anchor" href="#《象》曰-鼫鼠貞厲-位不當也。" aria-label="Permalink to “《象》曰：鼫鼠貞厲，位不當也。”">​</a></h3><p>位不當者，不中不正也。</p><p>六五，悔亡，失得勿恤，往吉，無不利。</p><p>恤者，憂也。中爻坎為加憂，恤之象也。五變，則中爻不成坎，故不憂，而勿恤矣。火無定體，倏然而活，倏然而沒，失得其常事也。凡易中遇離或錯離，或中爻離，皆言失得二字，如比卦九五錯離曰失前禽，隨卦六三變離曰失小子、隨有求得，噬嗑九四曰得金矢，六五曰得黃金，坎卦錯離，六二曰求小得，明夷九三曰得其大首，解卦九二錯離曰得黃矢，鼎卦初六曰得妾，震卦六二變中爻為離，曰七日得，漸卦中爻離六四曰得其桷，豐卦六二曰得疑疾，旅九四曰得資斧，巽上九變坎錯離曰喪其資斧。得失得喪，皆一意也，既濟六二曰七日得，未濟上九曰失是，則或失或得不以為意者，乃離之本有也，非戒辭也。本卦以象論，日出地上，乃朝日也，非日中之昃。以德論，居大明之中，而下順從之。以卦變論，為飛龍在天之君，六爻獨此爻善，所以《小象》曰“往有慶也”。悔亡者，中以行正也。失得勿恤者，虛中。則廓然太公，不以失得累其心也，故吉無不利。</p><p>六五柔中為自昭明德之主，天下臣民，莫不順而麗之，是以事皆悔亡，而心則不累於得失。持此以往，蓋吉而無不利者也。佔者有是德，斯應是佔矣。</p><h3 id="《象》曰-失得勿恤-往有慶也。" tabindex="-1">《象》曰：失得勿恤，往有慶也。 <a class="header-anchor" href="#《象》曰-失得勿恤-往有慶也。" aria-label="Permalink to “《象》曰：失得勿恤，往有慶也。”">​</a></h3><p>往有慶，即吉無不利。</p><p>上九，晉其角，維用伐邑。厲吉無咎，貞吝。</p><p>晉其角，與姤其角同。晉極明終日，已晚矣。角在首之上，晉其角，言欲進而前無其地矣，甚言其前無所進也。維者，維繫也，繫戀其三之陰私也。陽繫戀乎陰私，皆不光明之事，所以孔子《小象》但陽比於陰者，皆曰未光。離為兵戈，坤為眾，此爻變震，眾人戈兵震動，伐邑之象也。故離卦上九變震，亦曰王用出徵。邑即內卦坤之陰土也，詳見謙卦。伐邑，即同人伏戎於莽之意。凡《易經》爻辭，無其事而有此象，如此類者甚多。厲吉無咎者，言其理也。言邑若理可以伐，雖危厲亦吉而無咎也。吉無咎，即下文之貞也。貞吝者，言雖當伐，亦可羞也。</p><p>上九，明已極矣，又當晉之終，前無所進，此心維繫戀乎三爻所應之陰私而已，故有晉其角，維用伐邑之象。夫繫戀其私以伐邑，其道本不光明，然理若可伐而伐之，事雖危厲亦吉而無咎。但前無所進，既不能成康侯光明之業，反繫戀其私以伐邑，雖邑所當伐，其事故貞，亦可羞矣，安得吉而無咎哉。故戒佔者以此。</p><h3 id="《象》曰-維用伐邑-道未光也。" tabindex="-1">《象》曰：維用伐邑，道未光也。 <a class="header-anchor" href="#《象》曰-維用伐邑-道未光也。" aria-label="Permalink to “《象》曰：維用伐邑，道未光也。”">​</a></h3><p>此爻變震，下乃順體，陰陽相應，性順情動，豈有光明之事。</p>',38)])])}const f=e(l,[["render",t]]);export{_ as __pageData,f as default};
